import { Icon } from "@/registry/erbium/ui/icon";

import { RotatingChevron } from "@/registry/erbium/ui/stateful-icon";
import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import {
  Popover,
  PopoverContent,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/registry/erbium/ui/popover";
import { Separator } from "@/registry/erbium/ui/separator";
import { Textarea } from "@/registry/erbium/ui/textarea";

export default function ButtonGroupPopover() {
  return (
    <ButtonGroup>
      <Button variant="outline">
        <Icon name="bot" /> Copilot
      </Button>
      <Popover>
        <PopoverTrigger
          render={
            <Button
              variant="outline"
              size="icon"
              aria-label="Open Popover"
              className="group group/popover-trigger"
            >
              <RotatingChevron />
            </Button>
          }
        />
        <PopoverContent align="end" className="overflow-hidden rounded-xl">
          <PopoverHeader>
            <PopoverTitle>Agent Tasks</PopoverTitle>
          </PopoverHeader>
          <Separator />
          <div className="flex flex-col gap-related text-caption">
            <Textarea
              placeholder="Describe your task in natural language."
              className="resize-none"
            />
            <p className="font-medium">Start a new task with Copilot</p>
            <p className="text-muted-foreground">
              Describe your task in natural language. Copilot will work in the background and open a
              pull request for your review.
            </p>
          </div>
        </PopoverContent>
      </Popover>
    </ButtonGroup>
  );
}

import ExampleButtonGroupPopover from "../examples/button-group-popover";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleButtonGroupPopover />
  </div>
);

export default Example;
